//! Original optional intent facts from the same actual AgentCell decode.
//! JSON null means a present agent with no intent; no row means no agent.
use super::*;
use super::original_rows::{OriginalProjectionRowDataV1,OriginalProjectionRowsDataV1};
use std::cell::RefCell;
fn put(rows:&OriginalProjectionRowsDataV1,semantic:&[u8],key:&[u8],value:&[u8],common:&mut FormalBoundedContextV1<'_>)->Result<OriginalProjectionRowsDataV1,BodyMutationError>{let row=OriginalProjectionRowDataV1::from_original_encoded_data_v1(super::electricity::bytes(semantic,common)?,super::electricity::bytes(key,common)?,super::electricity::bytes(value,common)?,common)?;rows.with_row_data_v1(row,common)}
pub(super) fn from_seed_v1(seed:&NormalProjectionColumnSeedDataV1,common:&mut FormalBoundedContextV1<'_>)->Result<OriginalProjectionRowsDataV1,BodyMutationError>{seed.validate_context(common)?;let mut rows=OriginalProjectionRowsDataV1::empty_data_v1(common)?;for field in seed.fields(){common.consume_steps(1).map_err(paid)?;if field.descriptor().owner!=FieldOwner::WorldState||field.descriptor().name!="agents"{continue}for row in field.rows(){common.consume_steps(1).map_err(paid)?;let intent=row.agent_intent_v1().ok_or_else(||invalid("actual Agent intent source missing"))?;rows=put(&rows,row.semantic(),row.original_key_json(),intent,common)?}}Ok(rows)}
pub(super) fn apply_delta_v1(before:&OriginalProjectionRowsDataV1,source:&oasis7_world_state::incremental_agent_instance_projection_delta::CurrentAgentInstanceProjectionDeltaV1,common:&mut FormalBoundedContextV1<'_>)->Result<OriginalProjectionRowsDataV1,BodyMutationError>{let mut rows=before.share_data_v1(common)?;let shared=RefCell::new(common);source.visit_agent_intents_with_work_v1(|s,b|shared.borrow_mut().charge(s,b).map_err(paid),|semantic,key,value|{let mut common=shared.borrow_mut();rows=match value{Some(value)=>put(&rows,semantic,key,value,&mut common)?,None=>rows.without_row_data_v1(semantic,&mut common)?};Ok::<_,BodyMutationError>(())})?;Ok(rows)}
